-- Applied to production after actual-guess-fixes-and-repeat-guard.sql.
-- Open English WordNet, based on Princeton WordNet, by the Open English WordNet community.
-- Source: https://github.com/globalwordnet/english-wordnet/tree/9b6aca775ae10ad3d2dc9956e8ad42a4ce1e076b
-- License: CC BY 4.0; see source LICENSE.md and WNDB_License.txt.
-- Data is transformed to English member lists and selected relationship types.
-- Import only as administrator, in manageable batches. Do not call during game play.
-- ConceptNet staging is not activated for scoring: API returned HTTP 502 during testing.
-- If its data is eventually imported, preserve per-edge provenance and CC BY/CC BY-SA license.
-- No player information should be sent to public dictionary services.

-- 20261125013211 ascent_wordnet_knowledge_graph
create table ascent_game.wordnet_synsets(id text primary key, members text[] not null, relations jsonb not null, source_file text not null);
create table ascent_game.wordnet_imports(source_file text primary key, source_commit text not null, imported_at timestamptz not null default now(), rows int not null);
create table ascent_game.knowledge_edges(clue text not null,word text not null,relation text not null,source text not null,evidence text not null,strength smallint not null check(strength between 65 and 100),primary key(clue,word,relation,source));
alter table ascent_game.wordnet_synsets enable row level security;
alter table ascent_game.wordnet_imports enable row level security;
alter table ascent_game.knowledge_edges enable row level security;
revoke all on ascent_game.wordnet_synsets,ascent_game.wordnet_imports,ascent_game.knowledge_edges from public,anon,authenticated;
create index knowledge_edges_word_idx on ascent_game.knowledge_edges(word,clue);
create function ascent_game.import_wordnet_file(p_file text) returns integer language plpgsql volatile set search_path='' as $fn$
declare resp extensions.http_response; n int; source_commit constant text:='9b6aca775ae10ad3d2dc9956e8ad42a4ce1e076b';
begin
 if p_file !~ '^(noun|verb|adj|adv)\.[A-Za-z_]+\.yaml$' then raise exception 'Invalid WordNet file';end if;
 if exists(select 1 from ascent_game.wordnet_imports where source_file=p_file) then return 0;end if;
 perform set_config('http.curlopt_timeout_msec','10000',true);
 perform set_config('http.curlopt_connecttimeout_msec','2500',true);
 select * into resp from extensions.http_get('https://raw.githubusercontent.com/globalwordnet/english-wordnet/'||source_commit||'/src/yaml/'||p_file);
 if resp.status<>200 or length(resp.content)>6000000 then raise exception 'WordNet download failed: % %',p_file,resp.status;end if;
 insert into ascent_game.wordnet_synsets(id,members,relations,source_file)
 select substring(block from '^([0-9]{8}-[nvars]):'),
 array(select distinct lower(btrim(btrim(m[1],''''),'"')) from regexp_matches(coalesce(substring(block from E'\n  members:\n((?:  - [^\n]+\n?)+)'),''),E'  - ([^\n]+)','g') m where lower(btrim(btrim(m[1],''''),'"')) ~ '^[a-z][a-z0-9]*( [a-z0-9]+){0,5}$'),
 coalesce((select jsonb_object_agg(r[1],to_jsonb(array(select z[1] from regexp_matches(r[2],'([0-9]{8}-[nvars])','g') z))) from regexp_matches(block,E'\n  (hypernym|instance_hypernym|mero_part|mero_member|mero_substance|holo_part|holo_member|holo_substance|entails|causes|similar):\n((?:  - [0-9]{8}-[nvars]\n?)+)','g') r),'{}'),p_file
 from regexp_split_to_table(resp.content,E'\n(?=[0-9]{8}-[nvars]:\n)') block where block ~ '^[0-9]{8}-[nvars]:'
 on conflict(id) do nothing;
 get diagnostics n=row_count;
 if n<1 then raise exception 'No WordNet synsets parsed from %',p_file;end if;
 insert into ascent_game.wordnet_imports(source_file,source_commit,rows) values(p_file,source_commit,n);
 return n;
end;$fn$;
revoke all on function ascent_game.import_wordnet_file(text) from public,anon,authenticated;

