-- 20261125013306 ascent_index_wordnet_relations
create table ascent_game.wordnet_members(word text not null,synset text not null,primary key(word,synset));
alter table ascent_game.wordnet_members enable row level security;
revoke all on ascent_game.wordnet_members from public,anon,authenticated;
insert into ascent_game.wordnet_members select distinct m,s.id from ascent_game.wordnet_synsets s cross join lateral unnest(s.members) m on conflict do nothing;
create index wordnet_members_synset_idx on ascent_game.wordnet_members(synset);
create table ascent_game.wordnet_relations(src text not null,dst text not null,rel text not null,primary key(src,dst,rel));
alter table ascent_game.wordnet_relations enable row level security;
revoke all on ascent_game.wordnet_relations from public,anon,authenticated;
insert into ascent_game.wordnet_relations select distinct s.id, e.value #>> '{}',r.key from ascent_game.wordnet_synsets s cross join lateral jsonb_each(s.relations) r cross join lateral jsonb_array_elements(r.value) e join ascent_game.wordnet_synsets d on d.id=e.value #>> '{}' on conflict do nothing;
create index wordnet_relations_dst_idx on ascent_game.wordnet_relations(dst);
create function ascent_game.refresh_wordnet_edges() returns integer language plpgsql volatile set search_path='' as $fn$
declare n int;
begin
with active as (select distinct clue from ascent_game.association_scores_v7 union select distinct unnest(clues) from ascent_game.rich_tier_boards_v7),
anchors as materialized (select a.clue,m.synset from active a join ascent_game.wordnet_members m on m.word=a.clue),
paths as (
 select a.clue,a.synset dst,'synonym' relation,a.synset src,97 strength from anchors a
 union all select a.clue,r.dst,r.rel,r.src,case when r.rel in ('hypernym','instance_hypernym') then 85 when r.rel='similar' then 84 else 90 end from anchors a join ascent_game.wordnet_relations r on r.src=a.synset
 union all select a.clue,r.src,case r.rel when 'hypernym' then 'hyponym' when 'instance_hypernym' then 'instance' when 'mero_part' then 'holo_part' when 'mero_member' then 'holo_member' when 'mero_substance' then 'holo_substance' when 'holo_part' then 'mero_part' when 'holo_member' then 'mero_member' when 'holo_substance' then 'mero_substance' else r.rel end,r.dst,case when r.rel in ('hypernym','instance_hypernym') then 85 when r.rel='similar' then 84 else 90 end from anchors a join ascent_game.wordnet_relations r on r.dst=a.synset
), candidates as (
 select distinct on(p.clue,m.word,p.relation) p.clue,m.word,p.relation,'Open English WordNet' source,p.src||' → '||p.dst evidence,p.strength
 from paths p join ascent_game.wordnet_members m on m.synset=p.dst
 where m.word<>p.clue and m.word !~ '^[a-z]$'
 and m.word not in ('entity','physical entity','abstract entity','abstraction','object','physical object','thing','whole','unit','attribute','relation','property','substance','matter','someone','somebody','something','anything','everything','nothing','being','organism','act','action','activity','event','state','process','group','collection','type','kind','sort','category','class','set','part','component','element','item','person','individual','human','human being','causal agent','cause','effect','phenomenon','artifact','instrumentality')
 and p.clue not in ('entity','thing','object','something','anything','everything','nothing','act','action','activity','event','state','process','part','component','element','item','person','individual','human','being','group','collection','type','kind','sort','category','class','set')
 -- Only specific parent concepts; very broad parent synsets are not useful for a game.
 and (p.relation not in ('hypernym','hyponym','instance','instance_hypernym') or (select count(*) from ascent_game.wordnet_relations r where r.dst=case when p.relation in ('hyponym','instance') then p.src else p.dst end and r.rel in ('hypernym','instance_hypernym'))<=45)
 order by p.clue,m.word,p.relation,p.strength desc,p.src,p.dst
)
insert into ascent_game.knowledge_edges select clue,word,relation,source,evidence,strength from candidates on conflict do nothing;
get diagnostics n=row_count;return n;
end;$fn$;
revoke all on function ascent_game.refresh_wordnet_edges() from public,anon,authenticated;

select ascent_game.refresh_wordnet_edges();

-- 20261125013339 ascent_integrate_wordnet_into_live_scoring
create function ascent_game.knowledge_matches(clues text[],guess text,known jsonb) returns jsonb language sql stable set search_path='' as $fn$
with words as (
 select guess word union select left(guess,-1) where length(guess)>3 and guess like '%s' and guess not like '%ss'
 union select left(guess,-3)||'y' where guess like '%ies' and length(guess)>4
 union select left(guess,-2) where guess ~ '(ch|sh|s|x|z)es$'
), candidates as (
 select distinct on(k.clue) k.clue,case k.relation when 'synonym' then 'Same dictionary meaning' when 'hypernym' then 'A more general category' when 'hyponym' then 'A specific type' when 'mero_part' then 'Component relationship' when 'holo_part' then 'Component relationship' when 'mero_member' then 'Membership relationship' when 'holo_member' then 'Membership relationship' when 'mero_substance' then 'Material relationship' when 'holo_substance' then 'Material relationship' when 'similar' then 'Related dictionary meaning' else 'Direct dictionary relationship' end ||' — '||k.source||' ('||k.strength||'% match)' reason
 from ascent_game.knowledge_edges k join words w on w.word=k.word
 where k.clue=any(clues) and not known ? k.clue and k.word<>all(clues)
 and guess<>all(clues) and guess ~ '^[a-z0-9]+( [a-z0-9]+){0,7}$'
 and guess !~ '(^| )(not|unrelated|none|except|without|or)( |$)'
 order by k.clue,k.strength desc,k.relation,k.word
)
select known||coalesce((select jsonb_object_agg(clue,reason) from candidates),'{}')
$fn$;
revoke all on function ascent_game.knowledge_matches(text[],text,jsonb) from public,anon,authenticated;
do $patch$ declare d text;n text;begin
 select pg_get_functiondef('ascent_game.correct_spelling(text)'::regprocedure) into d;
 n:=replace(d,'if exists(select 1 from ascent_game.spelling_vocabulary where word=normalized)','if exists(select 1 from ascent_game.wordnet_members where word=normalized) or exists(select 1 from ascent_game.spelling_vocabulary where word=normalized)');
 if n=d then raise exception 'Spelling protection patch mismatch';end if;execute n;
 select pg_get_functiondef('ascent_game.semantic_complete_guess(text[],text,uuid,jsonb)'::regprocedure) into d;
 n:=replace(d,'if known=''{}''::jsonb then','known:=ascent_game.knowledge_matches(clues,normalized,known);
 if known=''{}''::jsonb then');
 n:=replace(n,'known:=ascent_game.complete_equivalent_answers(clues,corrected,known);','known:=ascent_game.complete_equivalent_answers(clues,corrected,known);
 known:=ascent_game.knowledge_matches(clues,corrected,known);');
 if n=d then raise exception 'Knowledge scorer patch mismatch';end if;execute n;
end;$patch$;
create or replace function ascent_game.preview_registered_guess(clues text[],guess text) returns jsonb language sql stable set search_path='' as $fn$
 with base as (select ascent_game.knowledge_matches(clues,guess,ascent_game.complete_equivalent_answers(clues,guess,ascent_game.match_guess(7,clues,guess))) known), v as (select embedding from ascent_game.semantic_word_vectors where word=guess)
 select known||coalesce((select ascent_game.vector_clue_matches(array(select c from unnest(clues) c where not known ? c),guess,embedding) from v where (select enabled from ascent_game.semantic_config where singleton)), '{}'::jsonb) from base
$fn$;
do $patch$ declare d text;n text;begin
 select pg_get_functiondef('public.ascent_top_answers(uuid,date,date,uuid,integer)'::regprocedure) into d;
 n:=replace(d,'count(*)::int hits,jsonb_object_agg(e.clue,e.value)','count(distinct e.clue)::int hits,jsonb_object_agg(e.clue,e.value)');
 n:=replace(n,' ) e where e.key<>all(b.clues)',' union all select k.clue,k.word,k.source from ascent_game.knowledge_edges k where b.lex_version=7 and k.clue=any(b.clues)
 ) e where e.key<>all(b.clues)');
 if n=d or n not like '%from ascent_game.knowledge_edges%' then raise exception 'Knowledge review patch mismatch';end if;execute n;
end;$patch$;

-- 20261125013407 ascent_missed_connection_feedback
create table ascent_game.connection_retry_evidence(day date not null,ticket uuid not null,scope text not null,pitch int not null,guess text not null,links jsonb not null,created_at timestamptz default now(),primary key(day,ticket,scope,pitch,guess));
create table ascent_game.connection_reports(day date not null,ticket uuid not null,scope text not null,pitch int not null,guess text not null,clue text not null,status text not null default 'pending' check(status in ('pending','accepted','dismissed')),created_at timestamptz not null default now(),primary key(day,ticket,scope,pitch,guess,clue));
alter table ascent_game.connection_retry_evidence enable row level security;
alter table ascent_game.connection_reports enable row level security;
revoke all on ascent_game.connection_retry_evidence,ascent_game.connection_reports from public,anon,authenticated;
do $patch$ declare d text;n text;begin
 select pg_get_functiondef('public.ascent_circuit(uuid,text,date,integer,text,date,uuid)'::regprocedure) into d;
 n:=replace(d,'   return jsonb_build_object(''links'',links,''points'',points,''rejected'',hits=0);','   if length(answer) between 1 and 120 and answer ~ ''^[a-z0-9]+( [a-z0-9]+){0,15}$'' and (select count(*) from ascent_game.connection_retry_evidence e where e.day=d and e.ticket=p_ticket and e.scope=run_scope and e.pitch=p_round)<30 then
    insert into ascent_game.connection_retry_evidence(day,ticket,scope,pitch,guess,links) values(d,p_ticket,run_scope,p_round,answer,links) on conflict(day,ticket,scope,pitch,guess) do update set links=excluded.links;
   end if;
   return jsonb_build_object(''links'',links,''points'',points,''rejected'',hits=0);');
 if n=d then raise exception 'Retry evidence patch mismatch';end if;execute n;
end;$patch$;
create function public.ascent_report_connection(p_ticket uuid,p_day date,p_round integer,p_guess text,p_clue text,p_archive date default null,p_seed uuid default null) returns jsonb language plpgsql volatile security definer set search_path='' as $fn$
declare scope_key text; h jsonb; matched jsonb; normalized text; report_day date;
begin
 if p_ticket is null or p_day is null or p_round not between 1 and 5 or (p_archive is not null and p_seed is not null) then return jsonb_build_object('ok',false);end if;
 scope_key:=case when p_seed is not null then 'practice:'||p_seed when p_archive=p_day then 'replay' else 'daily' end;
 report_day:=case when p_seed is not null then date '2026-11-24' else p_day end;
 if report_day<>p_day then return jsonb_build_object('ok',false);end if;
 normalized:=lower(btrim(regexp_replace(coalesce(p_guess,''),'[[:space:]]+',' ','g')));
 if length(normalized) not between 1 and 120 or normalized !~ '^[a-z0-9]+( [a-z0-9]+){0,15}$' then return jsonb_build_object('ok',false);end if;
 -- Only accept feedback from a previously revealed pitch associated with the caller's existing anonymous game ticket.
 select r.history->(p_round-1) into h from ascent_game.runs r where r.day=report_day and r.ticket=p_ticket and r.scope=scope_key and jsonb_array_length(r.history)>=p_round;
 if h is null or not (h->'clues' ? p_clue) or normalized in(select jsonb_array_elements_text(h->'clues')) then return jsonb_build_object('ok',false);end if;
 if h->>'guess'=normalized then matched:=h->'links';else
 select e.links into matched from ascent_game.connection_retry_evidence e where e.day=report_day and e.ticket=p_ticket and e.scope=scope_key and e.pitch=p_round and e.guess=normalized;
 end if;
 if matched is null or matched ? p_clue then return jsonb_build_object('ok',false);end if;
 perform pg_advisory_xact_lock(hashtextextended('ascent-report:'||p_ticket,0));
 if exists(select 1 from ascent_game.connection_reports r where r.day=report_day and r.ticket=p_ticket and r.scope=scope_key and r.pitch=p_round and r.guess=normalized and r.clue=p_clue) then return jsonb_build_object('ok',true,'duplicate',true);end if;
 if (select count(*) from ascent_game.connection_reports r where r.ticket=p_ticket and r.created_at>now()-interval '24 hours')>=30 then return jsonb_build_object('ok',false,'limited',true);end if;
 insert into ascent_game.connection_reports(day,ticket,scope,pitch,guess,clue) values(report_day,p_ticket,scope_key,p_round,normalized,p_clue) on conflict do nothing;
 return jsonb_build_object('ok',true);
end;$fn$;
revoke all on function public.ascent_report_connection(uuid,date,integer,text,text,date,uuid) from public;
grant execute on function public.ascent_report_connection(uuid,date,integer,text,text,date,uuid) to anon,authenticated;

