create function ascent_game.regression_result() returns table(clue text,guess text,expected boolean,actual boolean) language sql stable set search_path='' as $fn$
select c.clue,c.guess,c.expected,coalesce(ascent_game.preview_registered_guess(array[c.clue],ascent_game.correct_spelling(c.guess)) ? c.clue,false) from ascent_game.match_regression_cases c
$fn$;
revoke all on function ascent_game.regression_result() from public,anon,authenticated;

