-- 20261125013806 ascent_conceptnet_import_staging
create table ascent_game.conceptnet_stage(clue text not null,word text not null,relation text not null,source_uri text not null,license text not null,weight double precision not null,imported_at timestamptz default now(),primary key(clue,word,relation,source_uri));
alter table ascent_game.conceptnet_stage enable row level security;
revoke all on ascent_game.conceptnet_stage from public,anon,authenticated;
-- Private administrator-only importer. Only published clue words are sent;
-- never send player guesses or identifiers. Staging data does not award points.
create function ascent_game.stage_conceptnet_clue(p_clue text) returns integer language plpgsql volatile set search_path='' as $fn$
declare resp extensions.http_response; node text; n int;
begin
 if p_clue !~ '^[a-z0-9]+( [a-z0-9]+){0,5}$' or not exists(select 1 from ascent_game.association_scores_v7 where clue=p_clue) then return 0;end if;
 node:='/c/en/'||replace(p_clue,' ','_');
 perform set_config('http.curlopt_timeout_msec','5000',true);
 perform set_config('http.curlopt_connecttimeout_msec','1500',true);
 select * into resp from extensions.http_get('https://api.conceptnet.io/query?node='||node||'&other=/c/en&limit=100');
 if resp.status<>200 then return 0;end if;
 if jsonb_typeof(resp.content::jsonb->'edges') is distinct from 'array' then return 0;end if;
 insert into ascent_game.conceptnet_stage(clue,word,relation,source_uri,license,weight)
 select distinct p_clue,replace(split_part(other,'/',4),'_',' '),rel,edge->>'@id',edge->>'license',(edge->>'weight')::double precision
 from (
 select e edge,case when split_part(e->'start'->>'@id','/',4)=replace(p_clue,' ','_') then e->'end'->>'@id' else e->'start'->>'@id' end other,e->'rel'->>'@id' rel
 from jsonb_array_elements(resp.content::jsonb->'edges') e
 where (e->'start'->>'@id' like node||'/%' or e->'start'->>'@id'=node or e->'end'->>'@id' like node||'/%' or e->'end'->>'@id'=node)
 ) v
 where other like '/c/en/%' and replace(split_part(other,'/',4),'_',' ')<>p_clue
 and replace(split_part(other,'/',4),'_',' ') ~ '^[a-z0-9]+( [a-z0-9]+){0,5}$'
 and rel in ('/r/UsedFor','/r/CapableOf','/r/PartOf','/r/HasA','/r/MadeOf','/r/AtLocation','/r/ReceivesAction','/r/IsA','/r/Synonym','/r/HasProperty','/r/Causes','/r/RelatedTo')
 and jsonb_typeof(edge->'weight')='number' and (edge->>'weight')::double precision>=2
 and edge->>'license' in ('cc:by/4.0','cc:by-sa/4.0') and edge->>'@id' is not null
 on conflict do nothing;
 get diagnostics n=row_count;return n;
exception when others then return 0;
end;$fn$;
revoke all on function ascent_game.stage_conceptnet_clue(text) from public,anon,authenticated;

